pub fn fletcher4(r#in: &[u8]) -> Vec<u8> {
    let mut a: u64 = 0;
    let mut b: u64 = 0;
    let mut c: u64 = 0;
    let mut d: u64 = 0;
    let nwords = r#in.len() / 4;
    for i in 0..nwords {
        let w = ((r#in[i * 4] as u64)
            | ((r#in[i * 4 + 1] as u64) << 8)
            | ((r#in[i * 4 + 2] as u64) << 16)
            | ((r#in[i * 4 + 3] as u64) << 24)) as u32;
        a = a.wrapping_add(w as u64);
        b = b.wrapping_add(a);
        c = c.wrapping_add(b);
        d = d.wrapping_add(c);
    }
    let mut out = Vec::with_capacity(32);
    for i in 0..4 {
        let acc = match i {
            0 => a,
            1 => b,
            2 => c,
            3 => d,
            _ => unreachable!(),
        };
        for j in 0..8 {
            out.push(((acc >> (8 * j)) & 0xFF) as u8);
        }
    }
    out
}

