/// Fix16 Ssub
/// Subtracts two fixed-point 16.16 numbers with saturation on overflow, returning
/// the clamped result if the subtraction overflows.
pub fn fix16_ssub(a: i32, b: i32) -> i32 {
    let _a = a as u32;
    let _b = b as u32;
    let diff = _a.wrapping_sub(_b);

    if ((_a ^ _b) & 0x80000000) != 0 && ((_a ^ diff) & 0x80000000) != 0 {
        if a >= 0 {
            0x7fffffff
        } else {
            0x80000000u32 as i32
        }
    } else {
        diff as i32
    }
}

