pub fn fix16_mul(inArg0: i32, inArg1: i32) -> i32 {
    let product = (inArg0 as i64) * (inArg1 as i64);
    let upper = (product >> 47) as u32;
    if product < 0 {
        if upper != 0xFFFFFFFF {
            return i32::MIN;
        }
        let adjusted = product.wrapping_sub(1);
        let result = (adjusted >> 16) as i32;
        let rounding_bit = ((adjusted & 0x8000) >> 15) as i32;
        return result.wrapping_add(rounding_bit);
    } else {
        if upper != 0 {
            return i32::MIN;
        }
        let result = (product >> 16) as i32;
        let rounding_bit = ((product & 0x8000) >> 15) as i32;
        return result.wrapping_add(rounding_bit);
    }
}

