/// Fix16 Smul
/// Multiplies two 16-bit fixed-point numbers with saturation on overflow,
/// returning the maximum or minimum representable value when overflow occurs based
/// on the signs of the inputs.
pub fn fix16_smul(inArg0: i16, inArg1: i16) -> i16 {
    let a = inArg0 as i64;
    let b = inArg1 as i64;
    let product = a * b;
    let upper = ((product >> 47) & 0xFFFFFFFF) as u32;
    let overflow = if product < 0 {
        upper != 0xFFFFFFFF
    } else {
        upper != 0
    };
    if overflow {
        if (inArg0 >= 0) == (inArg1 >= 0) {
            i16::MAX
        } else {
            i16::MIN
        }
    } else {
        let result = (product >> 16) + ((product & 0x8000) >> 15);
        result as i16
    }
}

