pub fn base64_encode(plain: &[u8]) -> String {
    let base64_map = [
        b'A', b'B', b'C', b'D', b'E', b'F', b'G', b'H', b'I', b'J', b'K', b'L', b'M',
        b'N', b'O', b'P', b'Q', b'R', b'S', b'T', b'U', b'V', b'W', b'X', b'Y', b'Z',
        b'a', b'b', b'c', b'd', b'e', b'f', b'g', b'h', b'i', b'j', b'k', b'l', b'm',
        b'n', b'o', b'p', b'q', b'r', b's', b't', b'u', b'v', b'w', b'x', b'y', b'z',
        b'0', b'1', b'2', b'3', b'4', b'5', b'6', b'7', b'8', b'9', b'+', b'/',
    ];

    let mut counts = 0;
    let mut buffer = [0u8; 3];
    let mut cipher = Vec::with_capacity(plain.len() * 4 / 3 + 4);
    let mut i = 0;

    while i < plain.len() {
        buffer[counts as usize] = plain[i];
        counts += 1;
        if counts == 3 {
            cipher.push(base64_map[(buffer[0] >> 2) as usize]);
            cipher.push(base64_map[(((buffer[0] & 0x03) << 4) + (buffer[1] >> 4)) as usize]);
            cipher.push(base64_map[(((buffer[1] & 0x0f) << 2) + (buffer[2] >> 6)) as usize]);
            cipher.push(base64_map[(buffer[2] & 0x3f) as usize]);
            counts = 0;
        }
        i += 1;
    }

    if counts > 0 {
        cipher.push(base64_map[(buffer[0] >> 2) as usize]);
        if counts == 1 {
            cipher.push(base64_map[((buffer[0] & 0x03) << 4) as usize]);
            cipher.push(b'=');
        } else {
            cipher.push(base64_map[(((buffer[0] & 0x03) << 4) + (buffer[1] >> 4)) as usize]);
            cipher.push(base64_map[((buffer[1] & 0x0f) << 2) as usize]);
        }
        cipher.push(b'=');
    }

    String::from_utf8(cipher).expect("Invalid UTF-8 in base64 encoding")
}

