pub fn base64_decode(cipher: &str) -> Result<Vec<u8>, Base64Error> {
    let base64_map = [
        b'A', b'B', b'C', b'D', b'E', b'F', b'G', b'H', b'I', b'J', b'K', b'L', b'M',
        b'N', b'O', b'P', b'Q', b'R', b'S', b'T', b'U', b'V', b'W', b'X', b'Y', b'Z',
        b'a', b'b', b'c', b'd', b'e', b'f', b'g', b'h', b'i', b'j', b'k', b'l', b'm',
        b'n', b'o', b'p', b'q', b'r', b's', b't', b'u', b'v', b'w', b'x', b'y', b'z',
        b'0', b'1', b'2', b'3', b'4', b'5', b'6', b'7', b'8', b'9', b'+', b'/',
    ];
    let cipher_bytes = cipher.as_bytes();
    let mut counts: i8 = 0;
    let mut buffer: [u8; 4] = [0; 4];
    let mut plain = Vec::with_capacity(cipher_bytes.len() * 3 / 4);
    let mut i = 0;
    let mut p = 0;
    while i < cipher_bytes.len() {
        let mut k: u8 = 0;
        while k < 64 && base64_map[k as usize] != cipher_bytes[i] {
            k = k.wrapping_add(1);
        }
        buffer[counts as usize] = k;
        counts = counts.wrapping_add(1);
        if counts == 4 {
            plain.push((buffer[0] << 2) + (buffer[1] >> 4));
            if buffer[2] != 64 {
                plain.push((buffer[1] << 4) + (buffer[2] >> 2));
            }
            if buffer[3] != 64 {
                plain.push((buffer[2] << 6) + buffer[3]);
            }
            counts = 0;
            p = plain.len();
        }
        i = i.wrapping_add(1);
    }
    plain.push(0);
    plain.pop();
    Ok(plain)
}

