pub fn fix16_sqrt(inValue: i32) -> i32 {
    let neg = (inValue < 0) as u8;
    let num = if inValue < 0 {
        (-(inValue as i64) as u32)
    } else {
        inValue as u32
    };
    let mut result = 0u32;
    let mut bit;
    if num & 0xFFF00000 != 0 {
        bit = 1u32 << 30;
    } else {
        bit = 1u32 << 18;
    }
    while bit > num {
        bit >>= 2;
    }
    for _n in 0..2 {
        while bit != 0 {
            if num >= result.wrapping_add(bit) {
                num = num.wrapping_sub(result.wrapping_add(bit));
                result = (result >> 1).wrapping_add(bit);
            } else {
                result = result >> 1;
            }
            bit >>= 2;
        }
        if _n == 0 {
            if num > 65535 {
                num = num.wrapping_sub(result);
                num = (num << 16).wrapping_sub(0x8000);
                result = (result << 16).wrapping_add(0x8000);
            } else {
                num = num << 16;
                result = result << 16;
            }
            bit = 1u32 << 14;
        }
    }
    if num > result {
        result = result.wrapping_add(1);
    }
    if neg != 0 {
        -(result as i32)
    } else {
        result as i32
    }
}

