pub fn uleb128_encode(input_bytes: &[u8]) -> Vec<u8> {
    let mut buf = [0u8; 8];
    let n = input_bytes.len().min(8);
    for i in 0..n {
        buf[i] = input_bytes[i];
    }

    let mut v: u64 = 0;
    for i in 0..8 {
        v |= (buf[i] as u64) << (i * 8);
    }

    let mut out = Vec::new();
    loop {
        let mut byte = (v & 0x7f) as u8;
        v >>= 7;
        if v != 0 {
            byte |= 0x80;
        }
        out.push(byte);
        if v == 0 {
            break;
        }
    }
    out
}

