pub fn uleb128_decode(input_buffer: &[u8]) -> Vec<u8> {
    let mut v: u64 = 0;
    let mut shift: usize = 0;
    let mut i: usize = 0;
    let inlen = input_buffer.len();

    while i < inlen && shift < 64 {
        let b = input_buffer[i];
        i += 1;
        v |= ((b & 0x7f) as u64) << shift;
        if (b & 0x80) == 0 {
            break;
        }
        shift += 7;
    }

    let mut out = Vec::with_capacity(8);
    let bytes = v.to_le_bytes();
    out.extend_from_slice(&bytes);
    out
}

