    let mut i: usize = 0;
    let mut sign: i32 = 1;
    let mut v: i32 = 0;
    let n = data.len();

    if i < n && data[i] == b'-' {
        sign = -1;
        i += 1;
    } else if i < n && data[i] == b'+' {
        i += 1;
    }

    while i < n && data[i] >= b'0' && data[i] <= b'9' {
        v = v.wrapping_mul(10).wrapping_add((data[i] - b'0') as i32);
        i += 1;
    }

    v.wrapping_mul(sign)
}

