        return 0;
    }
    let mut r: u64 = (1u64 % m as u64);
    let mut b: u64 = (base as u64 % m as u64);
    let mut e = exp;

    while e > 0 {
        if (e & 1) != 0 {
            r = (r * b) % m as u64;
        }
        b = (b * b) % m as u64;
        e >>= 1;
    }

    r as u32
}

