}

pub fn gcd_binary(mut u: u32, mut v: u32) -> u32 {
    if u == 0 {
        return v;
    }
    if v == 0 {
        return u;
    }
    let mut s = 0;
    while ((u | v) & 1) == 0 {
        u >>= 1;
        v >>= 1;
        s += 1;
    }
    while (u & 1) == 0 {
        u >>= 1;
    }
    loop {
        while (v & 1) == 0 {
            v >>= 1;
        }
        if u > v {
            let t = u;
            u = v;
            v = t;
        }
        v = v.wrapping_sub(u);
        if v == 0 {
            break;
        }
    }
    u << s
}

