    while bit != 0 {
        let sum = res.wrapping_add(bit);
        if x >= sum {
            x = x.wrapping_sub(sum);
            res = (res >> 1).wrapping_add(bit);
        } else {
            res >>= 1;
        }
        bit >>= 2;
    }
    res
}

